param([string]$Runtime='win-x64',[Parameter(Mandatory=$true)][string]$CertificateThumbprint)
$ErrorActionPreference='Stop';dotnet publish ..\src\GManager.Client.Service -c Release -r $Runtime --self-contained -o ..\artifacts\service;dotnet publish ..\src\GManager.Client.Shell -c Release -r $Runtime --self-contained -o ..\artifacts\shell
$certificate=Get-Item "Cert:\CurrentUser\My\$CertificateThumbprint";Get-ChildItem ..\artifacts -Recurse -Filter *.exe|ForEach-Object{signtool sign /sha1 $CertificateThumbprint /fd SHA256 /tr http://timestamp.digicert.com /td SHA256 $_.FullName};Get-ChildItem ..\artifacts -Recurse -Filter *.ps1|ForEach-Object{Set-AuthenticodeSignature $_.FullName $certificate -TimestampServer http://timestamp.digicert.com|Out-Null};Get-ChildItem . -Filter *.ps1|Where-Object Name -ne 'publish.ps1'|ForEach-Object{Set-AuthenticodeSignature $_.FullName $certificate -TimestampServer http://timestamp.digicert.com|Out-Null}
Compress-Archive ..\artifacts\service, ..\artifacts\shell, install-service.ps1, uninstall-service.ps1 ..\artifacts\GManager.Client.zip -Force
